import React from 'react';
import { useNavigate } from 'react-router-dom';
import { Box, Typography, Button, Paper, useTheme, useMediaQuery } from '@mui/material';
import { Add as AddIcon } from '@mui/icons-material';
import AdminLayout from '../../../components/Layout/AdminLayout';
import AdminAppointmentList from '../../../components/AdminAppointmentList/AdminAppointmentList';
import { useQuery } from '@apollo/client';
import { GET_ALL_APPOINTMENTS } from '../../../graphql/admin';

const Appointments = () => {
  const navigate = useNavigate();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

  const { loading, error, data, refetch } = useQuery(GET_ALL_APPOINTMENTS, {
    fetchPolicy: 'network-only', // Always fetch fresh data
    onError: (error) => {
      console.error('Error loading appointments:', error);
    }
  });

  const handleNewAppointment = () => {
    navigate('/admin/appointments/new');
  };

  return (
    <AdminLayout>
      <Box 
        sx={{ 
          p: isMobile ? 1 : 0,
          width: '100%',
          boxSizing: 'border-box',
          flexGrow: 1,
          display: 'flex',
          flexDirection: 'column'
        }}
      >
        <Box 
          sx={{
            p: isMobile ? 2 : 3,
            pb: 0,
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            width: '100%',
            maxWidth: '100%',
            boxSizing: 'border-box',
            [theme.breakpoints.down('sm')]: {
              flexDirection: 'column',
              alignItems: 'flex-start',
              gap: 2,
              '& > *': {
                width: '100%'
              }
            }
          }}
        >
          <Typography variant="h4" component="h1" sx={{ fontWeight: 500, color: 'text.primary' }}>
            All Appointments
          </Typography>
          <Button
            variant="contained"
            color="primary"
            startIcon={<AddIcon />}
            onClick={handleNewAppointment}
            size={isMobile ? 'medium' : 'medium'}
            sx={{
              minWidth: 180,
              [theme.breakpoints.down('sm')]: {
                width: '100%',
                maxWidth: 300,
                mx: 'auto',
                display: 'block'
              }
            }}
          >
            New Appointment
          </Button>
        </Box>

        <Paper 
          sx={{ 
            p: { xs: 2, sm: 3 }, 
            borderRadius: 2,
            width: '100%',
            overflowX: 'auto'
          }}
        >
          <AdminAppointmentList 
            appointments={data?.allAppointments || []}
            loading={loading}
            error={error}
            onRefresh={() => refetch()}
          />
        </Paper>
      </Box>
    </AdminLayout>
  );
};

export default Appointments;
